using OpenAI;

// ---------------------------------------------------------------------------
// Configuration – set OPENAI_API_KEY (or OPENAI_BASE_URL to use a compatible
// provider). The model defaults to gpt-4o but can be overridden with
// OPENAI_MODEL.
// ---------------------------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? string.Empty;
var baseUrl = Environment.GetEnvironmentVariable("OPENAI_BASE_URL");
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o";

if (string.IsNullOrWhiteSpace(apiKey))
{
    Console.Error.WriteLine("Set the OPENAI_API_KEY environment variable to run this agent.");
    return 1;
}

var clientOptions = new OpenAI.OpenAIClientOptions();
if (!string.IsNullOrWhiteSpace(baseUrl))
    clientOptions.Endpoint = new Uri(baseUrl);

IChatClient chatClient = new OpenAI.Chat.ChatClient(model, new ApiKeyCredential(apiKey), clientOptions)
    .AsIChatClient();

// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------
var notebook = new Notebook();

var tools = new AIFunction[]
{
    AIFunctionFactory.Create(SearchWebAsync),
    AIFunctionFactory.Create(notebook.TakeNote),
    AIFunctionFactory.Create(notebook.GetNotes),
};

var chatOptions = new ChatOptions { Tools = [.. tools] };

// ---------------------------------------------------------------------------
// System prompt
// ---------------------------------------------------------------------------
const string SystemPrompt = """
    You are a research agent. The user will give you a topic to research.

    Your workflow:
    1. Break the topic into 2-3 focused search queries.
    2. Use the search_web tool for each query to gather information.
    3. As you find important facts, use the take_note tool to record them
       with a short title and the key details.
    4. After you have gathered enough information, use get_notes to review
       everything you recorded.
    5. Provide the user with a well-structured summary that synthesizes your
       findings, citing the sources where applicable.

    Be thorough but concise. Always search before answering.
    """;

// ---------------------------------------------------------------------------
// Agent loop
// ---------------------------------------------------------------------------
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║         🔍  Research Agent  🔍          ║");
Console.WriteLine("╠══════════════════════════════════════════╣");
Console.WriteLine("║  Enter a topic to research, or 'quit'.  ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Research topic> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notebook.Clear();

    var messages = new List<ChatMessage>
    {
        new(ChatRole.System, SystemPrompt),
        new(ChatRole.User, $"Research the following topic and provide a summary:\n\n{topic}"),
    };

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("\n⏳ Researching…\n");
    Console.ResetColor();

    // Agentic loop – keep going while the model wants to call tools.
    const int maxIterations = 20;
    for (var i = 0; i < maxIterations; i++)
    {
        var response = await chatClient.GetResponseAsync(messages, chatOptions);

        // Append all response messages to the conversation.
        messages.AddRange(response.Messages);

        if (response.Messages.Any(m => m.Contents.OfType<FunctionCallContent>().Any()))
        {
            // Process each tool call and add tool results.
            foreach (var msg in response.Messages)
            {
                foreach (var call in msg.Contents.OfType<FunctionCallContent>())
                {
                    Console.ForegroundColor = ConsoleColor.DarkYellow;
                    Console.WriteLine($"  🔧 {call.Name}({Summarize(call.Arguments)})");
                    Console.ResetColor();

