// ---------------------------------------------------------------------------
// Tool: Web search via DuckDuckGo HTML (no API key required)
// ---------------------------------------------------------------------------
[Description("Search the web for a query and return a summary of results including titles, snippets, and URLs.")]
static async Task<string> SearchWebAsync(
    [Description("The search query")] string query)
{
    using var http = new HttpClient();
    http.DefaultRequestHeaders.UserAgent.ParseAdd(
        "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

    try
    {
        var url = $"https://html.duckduckgo.com/html/?q={Uri.EscapeDataString(query)}";
        var html = await http.GetStringAsync(url);

        // Extract result snippets from the HTML.
        var results = new List<string>();
        var pos = 0;
        while (results.Count < 5)
        {
            var linkStart = html.IndexOf("class=\"result__a\"", pos, StringComparison.Ordinal);
            if (linkStart < 0) break;

            var title = ExtractTagContent(html, linkStart);
            var snippetStart = html.IndexOf("class=\"result__snippet\"", linkStart, StringComparison.Ordinal);
            var snippet = snippetStart >= 0 ? ExtractTagContent(html, snippetStart) : "";

            var hrefStart = html.LastIndexOf("href=\"", linkStart, Math.Min(linkStart, 200), StringComparison.Ordinal);
            var hrefUrl = "";
            if (hrefStart >= 0)
            {
                hrefStart += 6;
                var hrefEnd = html.IndexOf('"', hrefStart);
                if (hrefEnd > hrefStart)
                    hrefUrl = html[hrefStart..hrefEnd];
            }

            if (!string.IsNullOrWhiteSpace(title))
                results.Add($"- **{title.Trim()}**\n  {snippet.Trim()}\n  URL: {hrefUrl}");

            pos = linkStart + 1;
        }

        return results.Count > 0
            ? $"Search results for \"{query}\":\n\n{string.Join("\n\n", results)}"
            : $"No results found for \"{query}\".";
    }
    catch (Exception ex)
    {
        return $"Search failed: {ex.Message}";
    }
}

static string ExtractTagContent(string html, int startIndex)
{
    var open = html.IndexOf('>', startIndex);
    if (open < 0) return "";
    open++;
    var close = html.IndexOf('<', open);
    if (close < 0) return "";
    return System.Net.WebUtility.HtmlDecode(html[open..close].Trim());
}

static string Summarize(IDictionary<string, object?>? args)
{
    if (args is null || args.Count == 0) return "";
    return string.Join(", ", args.Select(kv =>
    {
        var val = kv.Value?.ToString() ?? "";
        if (val.Length > 60) val = val[..57] + "...";
        return $"{kv.Key}: \"{val}\"";
    }));
}

// ---------------------------------------------------------------------------
// Tool: Notebook for taking and reviewing notes
// ---------------------------------------------------------------------------
class Notebook
{
    private readonly List<(string Title, string Content)> _notes = [];

    [Description("Save a note with a title and content. Use this to record important findings during research.")]
    public string TakeNote(
        [Description("Short title for the note")] string title,
        [Description("The content / key facts to record")] string content)
    {
        _notes.Add((title, content));
        return $"Note saved: \"{title}\" ({_notes.Count} total notes)";
    }

    [Description("Retrieve all notes taken so far. Use this to review findings before writing the final summary.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes have been taken yet.";

        return string.Join("\n\n", _notes.Select((n, i) =>
            $"[{i + 1}] {n.Title}\n{n.Content}"));
    }

    public void Clear() => _notes.Clear();
}

